const PRICE = {
  input:       1.1   / 1_000_000,
  inputCached: 0.275 / 1_000_000,
  output:      4.4   / 1_000_000,
};

function pickUsage(obj = {}) {
  const v1 = obj.kwargs?.response_metadata?.usage;
  if (v1) {
    return {
      prompt:       v1.prompt_tokens       ?? v1.input_tokens       ?? 0,
      completion:   v1.completion_tokens   ?? v1.output_tokens      ?? 0,
      cached:       v1.prompt_tokens_details?.cached_tokens ?? 0,
    };
  }
  const v2 = obj.usage_metadata;
  if (v2) {
    return {
      prompt:       v2.input_tokens  ?? 0,
      completion:   v2.output_tokens ?? 0,
      cached:       v2.input_token_details?.cache_read ?? 0,
    };
  }
  const v3 = obj.usage;
  if (v3) {
    return {
      prompt:       v3.prompt_tokens ?? v3.input_tokens ?? 0,
      completion:   v3.completion_tokens ?? v3.output_tokens ?? 0,
      cached:       v3.cached_tokens ?? 0,
    };
  }
  return { prompt: 0, completion: 0, cached: 0 };
}

let promptT = 0, completionT = 0, cachedT = 0;
const steps = [];
let summary = '';

for (const item of $input.all()) {
  const conversations = Array.isArray(item.json) ? item.json : [item.json];

  for (const convo of conversations) {
    summary = convo.output ?? summary;

    if (Array.isArray(convo.intermediateSteps)) {
      for (const step of convo.intermediateSteps) {
        if (!step.action) continue;

        const msg = step.action.messageLog?.[0] ?? step.action;
        const u = pickUsage(msg);
        promptT     += u.prompt;
        completionT += u.completion;
        cachedT     += u.cached;

        steps.push({
          tool:        step.action.tool,
          toolInput:   step.action.toolInput,
          observation: step.observation,
        });
      }
    }
  }
}

const nonCached = promptT - cachedT;
const cost = (nonCached * PRICE.input) +
             (cachedT   * PRICE.inputCached) +
             (completionT * PRICE.output);

const result = {
  summary,
  promptTokens:     promptT,
  completionTokens: completionT,
  cachedTokens:     cachedT,
  costUSD:          +cost.toFixed(6),
  totalCostUSD:     +cost.toFixed(6), // opcional: pode remover se quiser evitar repetição
  steps
};

// --- Normalização pro Supabase (opcional se já tiver campos fixos na tabela) ---
const allKeys = [...new Set(Object.keys(result))];
const norm = {};
for (const key of allKeys) {
  norm[key] = result[key] ?? null;
}

return [{ json: norm }];

// Ordena as mensagens pela data
items.sort((a, b) => new Date(a.json.created_at) - new Date(b.json.created_at));

function formatarData(isoDate) {
  const d = new Date(isoDate);
  const dia = String(d.getDate()).padStart(2, '0');
  const mes = String(d.getMonth() + 1).padStart(2, '0');
  const ano = d.getFullYear();
  return `${dia}/${mes}/${ano}`;
}

const historico = [];

for (const item of items) {
  const row = item.json;
  const dataFormatada = formatarData(row.created_at);

  if (row.mensagem_usuario && row.mensagem_usuario.trim() !== "") {
    historico.push(`${dataFormatada} - Usuário: ${row.mensagem_usuario.trim()}`);
  }

  if (row.mensagem_agente && row.mensagem_agente.trim() !== "") {
    historico.push(`${dataFormatada} - Agente: ${row.mensagem_agente.trim()}`);
  }
}

return [
  {
    json: {
      historico_conversa: historico.join("\n\n")
    }
  }
];

const items = $input.all();

const processedItems = items.map(item => {
  // O n8n recebe o JSON do webhook dentro de .body
  const data = item.json.body || item.json;

  // Busca o telefone em múltiplas localizações possíveis do JSON do Chatwoot
  const phoneNumber = 
    data.sender?.phone_number || 
    data.conversation?.meta?.sender?.phone_number || 
    data.conversation?.contact?.phone_number || 
    "";

  const content = data.content || "";

  // Limpa o número: remove o '+' e mantém apenas dígitos
  const cleanNumber = phoneNumber.replace(/\D/g, '');

  /**
   * REGRAS DE VALIDAÇÃO:
   * 1. Comprimento entre 10 e 15 dígitos
   * 2. Ignora mensagens de sistema (Conectado com sucesso)
   * 3. Ignora números fakes de sistema (123456)
   */
  const isSystemMessage = content.includes("Conectado com sucesso");
  const isFakeNumber = cleanNumber === "123456" || cleanNumber === "";
  const hasValidLength = cleanNumber.length >= 10 && cleanNumber.length <= 15;

  const isValid = hasValidLength && !isSystemMessage && !isFakeNumber;

  return {
    json: {
      ...item.json,
      is_valid_phone: isValid,
      cleaned_phone: cleanNumber,
      debug_phone_found: phoneNumber // Campo para você conferir se ele achou o número
    }
  };
});

return processedItems;

// Nó: Code (JavaScript) — n8n | Fluxo 1.1
// Gera a lista de clientes válidos por tabela, marcando quem tem acréscimo de
// imposto (ES) e quem está sem tabela comercial. É isso que vai para o prompt.
// Os valores numéricos do cálculo NÃO vão para o agente — quem calcula é a tool.

const rows = $input.all().map(item => item.json);

// ─────────────────────────────────────────────────────────────
// 1. Localiza a linha de cabeçalho real
// ─────────────────────────────────────────────────────────────
const headerRow = rows.find(r =>
  Object.values(r).some(v => String(v ?? '').trim().toUpperCase() === 'INTERIOR')
);

if (!headerRow) {
  throw new Error('Cabeçalho não encontrado. Verifique o formato da planilha.');
}

const todasAsChaves = Object.keys(headerRow);

const idxInterior = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'INTERIOR'
);
const idxCapital = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'CAPITAL'
);

if (idxInterior === -1 || idxCapital === -1) {
  throw new Error('Colunas INTERIOR ou CAPITAL não encontradas no cabeçalho.');
}

const chavesInterior = todasAsChaves.slice(idxInterior - 1, idxCapital - 1);
const chavesCapital  = todasAsChaves.slice(idxCapital - 1);

function montarMapa(chaves) {
  const mapa = {};
  for (const chave of chaves) {
    const nome = String(headerRow[chave] ?? '').trim().toUpperCase();
    if (nome !== '') mapa[nome] = chave;
  }
  return mapa;
}

const mapaInterior = montarMapa(chavesInterior);
const mapaCapital  = montarMapa(chavesCapital);

// ─────────────────────────────────────────────────────────────
// 2. Acréscimo de imposto — sempre lido da planilha, nunca cravado
// ─────────────────────────────────────────────────────────────
// Lê a coluna TABELA e extrai os marcadores. Nenhum valor fica cravado no código:
//   "SOMAR 23,93% SOBRE O CTE (VALOR FINAL) (IMPOSTOS)"  -> acréscimo percentual
//   "R$50 taxa de coleta"                                -> taxa fixa de coleta
//   "GRIS SEMPRE"                                        -> GRIS aplicado sempre
//   "SEM TABELA"                                         -> cliente sem tabela comercial
function lerMarcadores(texto) {
  const bruto = String(texto ?? '').trim();
  const t = bruto.toUpperCase();

  const paraNumero = (s) => {
    if (!s) return 0;
    let v = String(s).trim();
    if (v.includes(',')) v = v.replace(/\./g, '').replace(',', '.');
    const n = parseFloat(v);
    return isFinite(n) ? n : 0;
  };

  const mPct = bruto.match(/SOMAR\s+([\d.,]+)\s*%/i);
  const pct = mPct ? paraNumero(mPct[1]) : 0;

  const mTaxa = bruto.match(/R\$\s*([\d.,]+)\s*(?:DE\s+)?TAXA/i)
             || bruto.match(/TAXA[^\d]{0,20}R\$\s*([\d.,]+)/i);
  const taxa = mTaxa ? paraNumero(mTaxa[1]) : 0;

  const semTabela = t === 'SEM TABELA';
  const grisSempre = /\bGRIS\s+SEMPRE\b/i.test(bruto);

  return {
    tabela: bruto,
    sem_tabela: semTabela,
    acrescimo_imposto: semTabela ? 0 : (pct > 0 ? pct / 100 : 0),
    taxa_coleta: semTabela ? 0 : (taxa > 0 ? taxa : 0),
    gris_sempre: semTabela ? false : grisSempre,
    tabela_nao_reconhecida:
      bruto !== '' && !semTabela && pct === 0 && taxa === 0 && !grisSempre,
  };
}

// ─────────────────────────────────────────────────────────────
// 3. Extrai os clientes de cada lado
// ─────────────────────────────────────────────────────────────
function extrairLado(mapa) {
  const saida = [];
  const vistos = new Set();

  for (const row of rows) {
    if (row === headerRow) continue;

    const nomeBruto = row[mapa['CLIENTE']];
    if (!nomeBruto) continue;
    const nome = String(nomeBruto).trim();
    if (nome === '' || nome.toUpperCase() === 'CLIENTE') continue;
    if (vistos.has(nome.toUpperCase())) continue;
    vistos.add(nome.toUpperCase());

    const marc = lerMarcadores(row[mapa['TABELA']]);

    saida.push({
      nome,
      sem_tabela: marc.sem_tabela,
      acrescimo_imposto_pct: Number((marc.acrescimo_imposto * 100).toFixed(2)),
      taxa_coleta: marc.taxa_coleta,
      gris_sempre: marc.gris_sempre,
    });
  }

  return saida.sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
}

const interior = extrairLado(mapaInterior);
const capital  = extrairLado(mapaCapital);

// ─────────────────────────────────────────────────────────────
// 4. Apelidos usados no dia a dia
// Precisa ficar em sincronia com o mapa APELIDOS do nó
// "Cálculo de frete (ad valorem + excedente)" do fluxo 1.2.
// ─────────────────────────────────────────────────────────────
const APELIDOS = {
  'QR LAB_UP LAB':                       ['UPLAB', 'UP LAB', 'QR LAB'],
  'BIOMIG MATERIAIS':                    ['BIOMIG'],
  'ADDLIFE / RESENDE':                   ['ADDLIFE', 'RESENDE'],
  'DML / INDAPHARMA':                    ['DML', 'INDAPHARMA'],
  'BPF COMERCIAL':                       ['BPF', 'KALYMINAS', 'I9'],
  'BIOSUL / GT GROUP':                   ['BIOSUL', 'GT GROUP'],
  'QUIBASA / USA DIAGNOSTICA (BIOCLIN)': ['QUIBASA', 'BIOCLIN'],
};

// ─────────────────────────────────────────────────────────────
// 5. Monta o texto que vai para o prompt
// ─────────────────────────────────────────────────────────────
const marcar = (c) => {
  let linha = c.nome;
  const apelidos = APELIDOS[c.nome.toUpperCase()];
  if (apelidos) linha += `  (também: ${apelidos.join(', ')})`;
  if (c.sem_tabela) return `${linha}  [SEM TABELA]`;
  const marcas = [];
  if (c.acrescimo_imposto_pct > 0) {
    marcas.push(`[ACRESCIMO ${String(c.acrescimo_imposto_pct).replace('.', ',')}%]`);
  }
  if (c.taxa_coleta > 0) {
    marcas.push(`[TAXA DE COLETA R$ ${c.taxa_coleta.toFixed(2).replace('.', ',')}]`);
  }
  // gris_sempre não é mais exibido: somar Ad Valorem/GRIS é comportamento padrão
  // de qualquer cliente que os tenha, então deixou de ser uma exceção pontual.
  return marcas.length ? `${linha}  ${marcas.join(' ')}` : linha;
};

const formatarLista = (arr) =>
  arr.map((c, i) => `${String(i + 1).padStart(2, '0')}. ${marcar(c)}`).join('\n');

const resumo =
  `CLIENTES — CAPITAL (${capital.length})\n` +
  `${formatarLista(capital)}\n\n` +
  `CLIENTES — INTERIOR (${interior.length})\n` +
  `${formatarLista(interior)}`;

return [{
  json: {
    clientes_capital:  capital.map(c => c.nome),
    clientes_interior: interior.map(c => c.nome),
    clientes_sem_tabela: [...new Set([...capital, ...interior].filter(c => c.sem_tabela).map(c => c.nome))],
    clientes_com_taxa_coleta: [...capital, ...interior].filter(c => c.taxa_coleta > 0)
      .map(c => `${c.nome} (R$ ${c.taxa_coleta.toFixed(2)})`),
    clientes_com_acrescimo: [...new Set([...capital, ...interior]
      .filter(c => c.acrescimo_imposto_pct > 0)
      .map(c => `${c.nome} (${String(c.acrescimo_imposto_pct).replace('.', ',')}%)`))],
    apelidos: APELIDOS,
    resumo_formatado: resumo
  }
}];

const texto = items[0].json.texto || '';

const textoEscapado = texto.replace(/\*/g, '\\*');

return [{
  json: {
    ...items[0].json,
    texto: textoEscapado
  }
}];

